@startuml

class Driver {
  + driverID : int
  + name : string
  + isOnSickLeave : boolean
}

class Bus {
  + licensePlate : string
  + isInRepairShop : boolean
}

class Route {
  + routeNumber : int
}

class Shift {
  + shiftType : ShiftType
}

enum ShiftType {
  Morning
  Afternoon
  Night
}

class Schedule {
  + date : date
}

class Assignment {
  + date : date
}

Driver "1" -- "*" Assignment
Bus "1" -- "*" Assignment
Route "1" -- "*" Assignment
Schedule "1" -- "*" Assignment
Assignment "1" -- "1" Shift

@enduml

